class Widget {
public:
    // A regular constructor
    Widget(int i, bool b) { /* ... */ }

    // An initializer-list constructor
    Widget(std::initializer_list<long double> il) { /* ... */ }
};

// Calls the regular constructor: Widget(int, bool)
Widget w1(10, true);

// Calls the std::initializer_list constructor!
// The compiler prefers it and converts 10 and true to long double.
Widget w2{10, true};
